function ladder(g, x, y0, y1, z, facing) {
  for (let y = y0; y <= y1; y++) g.set(x, y, z, "ladder", { facing });
}

// The chimney writes its whole stack, but earlier parts are locked: a flue cell where a roof already stands (the barn's
// back eave, the owner's eave) keeps what is there. Each such cell is warned, not written over.
function chimneyInAir(g, c) {
  const skipped = [];
  const airOnly = new Proxy(g, {
    get(t, p) {
      if (p === "set") return (x, y, z, b, s) => { if (t.isAir(x, y, z)) t.set(x, y, z, b, s); else skipped.push(`${x},${y},${z}`); return t; };
      const v = Reflect.get(t, p);
      return typeof v === "function" ? v.bind(t) : v;
    },
  });
  chimney(airOnly, c);
  if (skipped.length) console.warn("chimney", c.wall, "kept earlier cells:", skipped.join(" "));
}

export function build(g) {
  const notes = [];
  // chimneys, called directly (they lay their own footing and cut the mouth)
