input.new_string:
// The chimney writes its whole stack, but earlier parts are locked: a flue cell where a roof already stands (the barn's
// back eave, the owner's eave) keeps what is there. The locked cells are read before the chimney writes anything, so its
// own repeated writes still land; each kept cell is warned, not written over.
function chimneyInAir(g, c) {
  const locked = new Set();
  for (let x = 0; x < g.size[0]; x++) for (let y = 0; y < g.size[1]; y++) for (let z = 0; z < g.size[2]; z++)
    if (!g.isAir(x, y, z)) locked.add(`${x},${y},${z}`);
  const kept = new Set();
  const free = new Proxy(g, {
    get(t, p) {
      if (p === "set") return (x, y, z, b, s) => { const k = `${x},${y},${z}`; if (locked.has(k)) kept.add(k); else t.set(x, y, z, b, s); return t; };
      const v = Reflect.get(t, p);
      return typeof v === "function" ? v.bind(t) : v;
    },
  });
  chimney(free, c);
  if (kept.size) console.warn("chimney", c.wall, "kept earlier cells:", [...kept].join(" "));
}

