// Part: chimneys, stairs, hearths, job sites
import { chimney, flight, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { jobSite } from "../vocab.mjs";

function ladder(g, x, y0, y1, z, facing) {
  for (let y = y0; y <= y1; y++) g.set(x, y, z, "ladder", { facing });
}

// The chimney writes its whole stack, but earlier parts are locked: a flue cell where a roof already stands (the barn's
// back eave, the owner's eave) keeps what is there. The locked cells are read before the chimney writes anything, so its
// own repeated writes still land; each kept cell is warned, not written over.
function chimneyInAir(g, c) {
  const locked = new Set();
  for (let x = 0; x < g.size[0]; x++) for (let y = 0; y < g.size[1]; y++) for (let z = 0; z < g.size[2]; z++)
    if (!g.isAir(x, y, z)) locked.add(`${x},${y},${z}`);
  const kept = new Set();
  const free = new Proxy(g, {
    get(t, p) {
      if (p === "set") return (x, y, z, b, s) => { const k = `${x},${y},${z}`; if (locked.has(k)) kept.add(`${k} wants ${b} has ${t.blockAt(x, y, z)}`); else t.set(x, y, z, b, s); return t; };
      const v = Reflect.get(t, p);
      return typeof v === "function" ? v.bind(t) : v;
    },
  });
  chimney(free, c);
  if (kept.size) console.warn("chimney", c.wall, "kept earlier cells:", [...kept].join(" "));
}

export function build(g) {
  const notes = [];
  // chimneys, called directly (they lay their own footing and cut the mouth)
  const chims = [
    { wall: [32, 2, 15], into: "west", top: 13 },
    { wall: [40, 1, 15], into: "north", top: 12 },
    { wall: [65, 1, 15], into: "north", top: 13 },
    { wall: [91, 2, 15], into: "north", top: 16 },
  ];
  for (const c of chims) {
    try { chimneyInAir(g, { ...c, material: "bricks" }); } catch (e) { console.warn("chimney", c.wall, e.message); }
  }
  // flights
  for (const f of [
    { from: [26, 2, 13], facing: "east", to: 6, material: "spruce" },
    { from: [86, 2, 14], facing: "north", to: 6, material: "spruce" },
  ]) {
    try { const r = flight(g, f); if (r.notes?.length) console.warn("flight", r.notes); } catch (e) { console.warn("flight", e.message); }
  }
  // ladders
  ladder(g, 2, 1, 6, 15, "east");
  ladder(g, 52, 9, 15, 11, "north");
  ladder(g, 55, 2, 7, 16, "west");
  ladder(g, 64, 1, 9, 14, "east");
  // job sites
  jobSite(g, "cartography_table", [21, 2, 16], { facing: "north" });
  jobSite(g, "smithing_table", [43, 1, 14], { facing: "west" });
  jobSite(g, "anvil", [42, 1, 12], { facing: "north" });
  jobSite(g, "lectern", [52, 2, 16], { facing: "north" });
  jobSite(g, "composter", [78, 2, 15], { facing: "north" });
  // forge quench
  g.set(41, 1, 14, "water_cauldron", { level: "3" });
}

