      const v = Reflect.get(t, p);
      return typeof v === "function" ? v.bind(t) : v;
    },
  });
  chimney(skipEaves, c);
  if (kept.length) console.warn("chimney", c.wall, "kept the roof's eave at", kept.join(" "));
}

